// -----------------------------------------------------------------------
// EDIT THIS: your real, factual background. The prompt is explicitly told
// never to invent anything outside this block - that is the hallucination guard.
// -----------------------------------------------------------------------
const FACTS = `
Name: Your Name
Role: Backend / automation engineer, 2 years experience
Currently: builds internal tooling with Node.js, TypeScript, PostgreSQL, Docker
Shipped: an n8n pipeline that ingests ~1,200 job postings/month with dedupe and LLM scoring
Shipped: a REST API serving 50k requests/day on AWS ECS
Certifications: AWS Cloud Practitioner
Strongest skills: JavaScript, TypeScript, Python, SQL, Docker, API design, n8n
Limitations: no Kubernetes in production, no formal ML training
`.trim();

const job = $input.first().json;
if (!job || job.id === undefined) {
  return [{ json: { empty: true, note: 'No unscored job with score >= 70. Run 01 and 02 first, or lower the threshold.' } }];
}

const jd = String(job.description || '').slice(0, 4000);
const keywords = (job.matched_keywords || []).slice(0, 8).join(', ');

const system =
  'You write short, specific cover letters. Rules: (1) use ONLY facts from the CANDIDATE block, ' +
  '(2) never invent employers, degrees, metrics or skills, (3) if the candidate lacks something the job asks for, do not claim it, ' +
  '(4) 110-150 words, plain text, no markdown, no greeting placeholder other than "Dear <Company> team", ' +
  '(5) mention at most 3 overlapping technologies, (6) end with one concrete sentence about what the candidate would do in week one.';

const user =
  'CANDIDATE\n' + FACTS + '\n\nJOB\nTitle: ' + job.title + '\nCompany: ' + job.company + '\nLocation: ' + (job.location || 'n/a') +
  '\nOverlapping keywords detected: ' + (keywords || 'none') + '\n\nJOB DESCRIPTION\n' + jd +
  '\n\nWrite the cover letter now.';

return [{ json: { job_id: Number(job.id), title: job.title, company: job.company, system, user, model: 'openai/gpt-oss-120b' /* Groq retired llama-3.3; gpt-oss is a reasoning model, so the request uses reasoning_effort: low + 1200 tokens */, prompt_version: 'v1' } }];

const text =
  ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message.content) || '';
const p = $('Build prompt').first().json;
if (!text.trim()) return [{ json: { empty: true, note: 'Model returned nothing. Check the Groq response in the execution log.' } }];

const q = (v) => "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
return [
  {
    json: {
      job_id: p.job_id,
      company: p.company,
      title: p.title,
      letter: text.trim(),
      save_sql:
        "UPDATE jobs SET cover_letter = " + q(text.trim()) + ", status = 'shortlisted', updated_at = now() WHERE id = " + p.job_id + ';',
    },
  },
];

return [
  {
    json: {
      skipped: true,
      reason: 'GROQ_API_KEY is empty, so the AI branch is bypassed on purpose.',
      next: 'Add a free key to .env, restart with docker compose up -d, then run this workflow again.',
    },
  },
];
